import java.util.*;

public class Main {
    static long pow_mod(long base, long exp) {
        long res = 1;
        long mod = 1000000007;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static class UnionFind {
        int[] parent;
        int[] rank;
        int count;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            count = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int u) {
            if (parent[u] != u) {
                parent[u] = find(parent[u]);
            }
            return parent[u];
        }

        public void unite(int u, int v) {
            u = find(u);
            v = find(v);
            if (u != v) {
                if (rank[u] < rank[v]) {
                    int temp = u;
                    u = v;
                    v = temp;
                }
                parent[v] = u;
                if (rank[u] == rank[v]) {
                    rank[u]++;
                }
                count--;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        boolean[] visited = new boolean[(int) p];
        UnionFind uf = new UnionFind((int) p);
        for (long i = 0; i < p; i++) {
            for (long j = i; !visited[(int) j]; j = (j * k) % p) {
                visited[(int) j] = true;
                uf.unite((int) i, (int) j);
            }
        }
        int c = uf.count;
        if (k != 1) c--;
        System.out.println(pow_mod(p, c));
        sc.close();
    }
}
